toad_implementation.code_blueprint:
canvas {
  size: 800px 920px;
  fill: #FFF066;
  font-family: "Archivo Black, sans-serif";
}

>lemon = #FFF066;
>coral = #FF6F59;
>teal = #254441;
>aqua = #43BCCD;

circle #confetti1 {
  at: top left of canvas offset 60px 80px;
  size: 28px;
  fill: >coral;
}

circle #confetti2 {
  at: top right of canvas offset -80px 100px;
  size: 36px;
  fill: >aqua;
}

rect #mainCardShadow {
  at: center of canvas offset 8px 8px;
  size: 520px 520px;
  fill: >teal;
}

rect #mainCard {
  at: center of canvas;
  size: 520px 520px;
  fill: #FFFFFF;
  stroke: >teal;
  stroke-width: 5px;
}

circle #innerSemiDisc {
  at: top center of #mainCard offset 0px 60px;
  size: 200px;
  fill: >coral;
}

rect #crossStripe {
  at: center of #mainCard offset 0px 40px;
  size: 400px 32px;
  fill: >aqua;
  stroke: >teal;
  stroke-width: 4px;
  rotation: -8deg;
}

text #memphisHero {
  at: center of #mainCard offset 0px 120px;
  content: "P O P !";
  font-size: 72px;
  font-weight: 900;
  color: >teal;
}

text #taglineContainer {
  at: below #mainCard offset 36px;
  content: "NEO-MEMPHIS DESIGN SYNDICATE";
  font-size: 16px;
  font-weight: 900;
  color: >teal;
}
